import { lazy, Suspense, useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { Activity, Bell, Box, Download, FileText, FolderOpen, Play, RefreshCw, Terminal } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { api } from '../api';
import type { Server } from '../types';
import type { DevSyncPair } from '../types';
import type { GpuDiagnostics, ExperimentWorkspace, SlurmResult, AlertRule, CommandTemplate, ContainerList, EnvEntry, GpuWatch, LogWatcher, ResourceReport, ServiceTemplate, SystemResources, UsageRow, WorkbenchEvent, WorkspaceTask } from '../workbench-types';
import { downloadText, csvCell } from '../telemetry/history-view';
import { Sparkline } from './Sparkline';
import { exportPresentationBackup, stagePresentationImport, settlePresentationImport, validatePresentationBackup } from '../telemetry/config-backup';
import { useLiveServer } from '../telemetry/store';
import './workcenter.css';

const ResearchPane = lazy(() => import('./ResearchPane'));

type Tab = 'experiments' | 'workspaces' | 'gpuDiagnostics' | 'slurm' | 'tools' | 'system' | 'tasks' | 'watches' | 'logs' | 'sync' | 'containers' | 'services' | 'reports' | 'commands';
export function WorkCenter({ servers, initialServerId, initialProcessId, onTerminal, onFiles, onForward }: {
  servers: Server[]; initialServerId?: string; initialProcessId?: number;
  onTerminal: (serverId: string, command?: string) => void; onFiles: (serverId: string, path?: string) => void;
  onForward: (serverId: string, template: ServiceTemplate) => Promise<void>;
}) {
  const { t } = useTranslation();
  const label = useCallback((key: string, fallback: string) => t('features.' + key, { defaultValue: fallback }), [t]);
  const [serverId, setServer] = useState(initialServerId || servers[0]?.id || '');
  const [tab, setTab] = useState<Tab>('system'), [error, setError] = useState(''), [busy, setBusy] = useState(false), [revision, setRevision] = useState(0);
  const scope = serverId + ':' + tab;
  const currentScope = useRef(scope), generation = useRef(0);
  if (currentScope.current !== scope) { currentScope.current = scope; generation.current += 1; }
  const requestGeneration = generation.current;
  const pending = useRef(false), mounted = useRef(true);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  const [resources, setResources] = useState<SystemResources | null>(null), [tasks, setTasks] = useState<WorkspaceTask[]>([]), [watches, setWatches] = useState<GpuWatch[]>([]);
  const [rules, setRules] = useState<AlertRule[]>([]), [events, setEvents] = useState<WorkbenchEvent[]>([]), [containers, setContainers] = useState<ContainerList | null>(null);
  const [gpuDiagnostics, setGpuDiagnostics] = useState<GpuDiagnostics | null>(null);
  const [report, setReport] = useState<ResourceReport | null>(null), [templates, setTemplates] = useState<CommandTemplate[]>([]), [output, setOutput] = useState('');
  const [logWatchers, setLogWatchers] = useState<LogWatcher[]>([]), [envs, setEnvs] = useState<EnvEntry[]>([]), [usage, setUsage] = useState<UsageRow[] | null>(null);
  const [pairs, setPairs] = useState<DevSyncPair[]>([]);
  const [workspaces, setWorkspaces] = useState<ExperimentWorkspace[]>([]), [slurm, setSlurm] = useState<SlurmResult | null>(null);
  const [workspaceForm, setWorkspaceForm] = useState({ name: '', cwd: '', gpu: '', taskId: '', sessionName: '', logPath: '', remotePort: '', localPort: '' });
  const [jobId, setJobId] = useState('');
  const [selectedWorkspace, setSelectedWorkspace] = useState('');
  const [editingLog, setEditingLog] = useState<{ id: string; enabled: boolean } | null>(null);
  const notificationDirty = useRef(false);
  const [notification, setNotification] = useState({ enabled: false, url: '', quietStart: '', quietEnd: '' });
  const [diagnosticsOutput, setDiagnosticsOutput] = useState('');
  const [backup, setBackup] = useState(''), [backupPreview, setBackupPreview] = useState<unknown>(null);
  const [backupReading, setBackupReading] = useState(false);
  const [importResults, setImportResults] = useState<Array<{ operationId: string; status: string; error?: string; at: number }>>([]);
  const backupRevision = useRef(0), reviewedBackup = useRef('');
  const liveServer = useLiveServer(servers.find((server) => server.id === serverId));

  const [form, setForm] = useState({ name: '', cwd: '~', command: '', gpu: '', model: '', free: '40', seconds: '30', metric: 'temperature', threshold: '85', recovery: '80', cooldown: '300', quietStart: '', quietEnd: '', pid: initialProcessId ? String(initialProcessId) : '', service: 'jupyter', remotePort: '8888', localPort: '8888', logDir: './runs', parameters: '{}', schedEnabled: '', schedStart: '00:00', schedEnd: '06:00', schedDays: '0123456', logName: '', logPath: '', logPatterns: '', logMode: 'literal', logLoss: '', usageDays: '30', syncLocal: '', syncRemote: '', syncExcludes: '' });
  const usageRangeRef = useRef(form.usageDays); usageRangeRef.current = form.usageDays;
  const set = useCallback((key: keyof typeof form, value: string) => setForm((previous) => ({ ...previous, [key]: value })), []);
  const request = useCallback(async <T,>(operation: string, extra: Record<string, unknown> = {}): Promise<T> => {
    if (!api) throw new Error(label('desktopRequired', 'Open the desktop application to use remote tools.'));
    const startedGeneration = requestGeneration;
    if (!mounted.current || generation.current !== startedGeneration) throw new Error('Request context changed');
    const result = await api.workbenchRequest<T>({ operation, serverId, ...extra });
    if (!result.ok || result.data === undefined) throw new Error(result.error || 'Operation failed');
    if ((!mounted.current || generation.current !== startedGeneration) && !(operation === 'backupImport' && extra.apply === true)) throw new Error('Request context changed');
    return result.data;
  }, [serverId, requestGeneration, label]);
  const run = async (fn: () => Promise<void>) => {
    if (pending.current) return;
    const startedGeneration = requestGeneration; pending.current = true; setBusy(true); setError('');
    try { await fn(); if (mounted.current && generation.current === startedGeneration) setRevision((n) => n + 1); }
    catch (e) { if (mounted.current && generation.current === startedGeneration) setError(String(e)); }
    finally { pending.current = false; if (mounted.current) setBusy(false); }
  };
  useEffect(() => { if (initialServerId && !pending.current) setServer(initialServerId); }, [initialServerId]);
  useEffect(() => { setWorkspaceForm((previous) => ({ ...previous, cwd: '' })); }, [serverId]);
  useEffect(() => {
    if (!serverId || tab !== 'workspaces' || !api) return;
    let cancelled = false;
    void api.sftpHome(serverId).then((result) => {
      if (!cancelled && result.ok && result.data?.startsWith('/')) setWorkspaceForm((previous) => previous.cwd ? previous : { ...previous, cwd: result.data! });
    }).catch(() => {});
    return () => { cancelled = true; };
  }, [serverId, tab]);
  useEffect(() => { if (initialProcessId && !pending.current) { set('pid', String(initialProcessId)); setTab('system'); } }, [initialProcessId, initialServerId, set]);
  useLayoutEffect(() => { setSelectedWorkspace(''); setEditingLog(null); setOutput(''); setResources(null); setContainers(null); setReport(null); setTasks([]); setWatches([]); setRules([]); setEvents([]); setTemplates([]); setLogWatchers([]); setEnvs([]); setUsage(null); setPairs([]); setWorkspaces([]); setGpuDiagnostics(null); setSlurm(null); setDiagnosticsOutput(''); setBackup(''); setBackupPreview(null); backupRevision.current++; reviewedBackup.current = ''; setBackupReading(false); notificationDirty.current = false; setNotification({ enabled: false, url: '', quietStart: '', quietEnd: '' }); setError(''); }, [serverId]);
  useEffect(() => { if (!servers.some((s) => s.id === serverId)) setServer(servers[0]?.id || ''); }, [servers, serverId]);
  useEffect(() => {
    if (!serverId || !api) return;
    let disposed = false, pending = false;
    setError('');
    const load = async () => {
      if (pending) return; pending = true;
      try {
        if (tab === 'workspaces') { const [values, savedTasks] = await Promise.all([request<ExperimentWorkspace[]>('workspaceList'), request<WorkspaceTask[]>('taskList')]); if (!disposed) { setWorkspaces(values); setTasks(savedTasks); } }
        else if (tab === 'slurm') { const result = await request<SlurmResult>('slurmJobs'); if (!disposed) setSlurm(result); }
        else if (tab === 'tools') { const [result, imports] = await Promise.all([request<{ enabled: boolean; configured?: boolean; endpoint?: string }>('notificationGet'), request<typeof importResults>('backupResults')]); if (!disposed) { setImportResults(Array.isArray(imports) ? imports : []); if (!notificationDirty.current) setNotification((old) => ({ ...old, enabled: result.enabled })); } }
        else if (tab === 'system') { const [res, env] = await Promise.allSettled([request<SystemResources>('system'), request<EnvEntry[]>('envList')]); if (!disposed) { if (res.status === 'fulfilled') setResources(res.value); if (env.status === 'fulfilled') setEnvs(env.value); const failed = [res, env].find((r) => r.status === 'rejected'); if (failed && failed === res && env.status === 'rejected') throw failed.reason; } }
        else if (tab === 'tasks') { let values = await request<WorkspaceTask[]>('taskList'); values = await Promise.all(values.map((task) => task.remoteId && ['starting', 'running', 'unknown'].includes(task.status) ? request<WorkspaceTask>('taskStatus', { id: task.id }) : Promise.resolve(task))); if (!disposed) setTasks(values); }
        else if (tab === 'watches') { const [ws, rs, es] = await Promise.all([request<GpuWatch[]>('watchList'), request<AlertRule[]>('ruleList'), request<WorkbenchEvent[]>('eventList')]); if (!disposed) { setWatches(ws); setRules(rs); setEvents(es); } }
        else if (tab === 'logs') { const value = await request<LogWatcher[]>('logList'); if (!disposed) setLogWatchers(value); }
        else if (tab === 'sync' && api) { const value = await api.devsyncList(); if (!disposed) { if (value.ok && value.data) setPairs(value.data); else throw new Error(value.error || 'devsync failed'); } }
        else if (tab === 'containers') { const value = await request<ContainerList>('containers'); if (!disposed) setContainers(value); }
        else if (tab === 'commands') { const value = await request<CommandTemplate[]>('templateList'); if (!disposed) setTemplates(value); }
        else if (tab === 'reports') { const value = await request<UsageRow[]>('usageReport', { rangeDays: Number(usageRangeRef.current) }); if (!disposed) setUsage(value); }
      } catch (e) { if (!disposed) setError(String(e)); } finally { pending = false; }
    };
    void load(); const timer = setInterval(() => { void load(); }, tab === 'containers' ? 10000 : 5000);
    return () => { disposed = true; clearInterval(timer); };
  }, [serverId, tab, request, revision]);
  const input = (key: keyof typeof form, title: string, type = 'text') => <label>{title}<input type={type} value={form[key]} onChange={(e) => set(key, e.target.value)} /></label>;
  const bytes = (value: number | null) => value == null ? '—' : value >= 1073741824 ? (value / 1073741824).toFixed(1) + ' GiB' : value >= 1048576 ? (value / 1048576).toFixed(1) + ' MiB' : (value / 1024).toFixed(1) + ' KiB';
  const tabs: Array<[Tab, string]> = [['system', label('systemTools', 'System')], ['tasks', label('tasks', 'Tasks')], ['watches', label('rulesAndWatches', 'Reminders & rules')], ['logs', label('logWatchers', 'Log watchers')], ['sync', label('syncTitle', 'Save & upload')], ['containers', label('containers', 'Containers')], ['services', label('services', 'Services')], ['reports', label('reports', 'Reports')], ['commands', label('commandTemplates', 'Command templates')]];
  const groups: Array<{ key: string; title: string; tabs: Tab[] }> = [
    { key: 'run', title: label('groupRun', 'Run'), tabs: ['workspaces', 'experiments', 'tasks', 'containers', 'slurm'] },
    { key: 'observe', title: label('groupObserve', 'Observe'), tabs: ['system', 'gpuDiagnostics', 'watches', 'logs', 'reports'] },
    { key: 'files', title: label('groupFiles', 'Files'), tabs: ['sync'] },
    { key: 'tools', title: label('groupTools', 'Tools'), tabs: ['services', 'commands', 'tools'] },
  ];
  const titleOf = (key: Tab) => key === 'experiments' ? t('research.title') : tabs.find(([id]) => id === key)?.[1] || label(key, key === 'workspaces' ? 'Experiment workspaces' : key === 'gpuDiagnostics' ? 'GPU diagnostics' : key === 'slurm' ? 'Slurm jobs' : 'Diagnostics & backup');

  const envServers = servers.filter((s) => envs.some((e) => e.serverId === s.id));
  const envOf = (sid: string) => envs.find((e) => e.serverId === sid);
  const envFields: Array<[string, string, (e: EnvEntry) => string]> = [
    ['envDriver', 'Driver', (e) => e.driver || '—'], ['envCuda', 'CUDA', (e) => e.cuda || '—'],
    ['envKernel', 'Kernel / OS', (e) => (e.kernel || '—') + (e.os ? ' · ' + e.os : '')],
    ['envPython', 'Python', (e) => e.python || '—'], ['envTorch', 'PyTorch + CUDA', (e) => e.torch || '—'],
  ];
  const usageText = (minutes: number) => minutes >= 60 ? (minutes / 60).toFixed(1) + ' h' : minutes.toFixed(minutes < 10 ? 1 : 0) + ' min';
  const expectOk = async <T,>(promise: Promise<{ ok: boolean; data?: T; error?: string }> | undefined, fallback: T): Promise<T> => { void fallback;
    if (!promise) throw new Error(label('desktopRequired', 'Open the desktop application to use remote tools.'));
    const result = await promise;
    if (!result.ok || result.data === undefined) throw new Error(result.error || 'Operation failed');
    return result.data;
  };
  const workspaceSet = (key: keyof typeof workspaceForm, value: string) => setWorkspaceForm((old) => ({ ...old, [key]: value }));
  const shellQuote = (value: string) => "'" + value.replace(/'/g, "'\\''") + "'";
  const openWorkspace = (workspace: ExperimentWorkspace, view: 'term' | 'files') => { if (view === 'files') onFiles(workspace.serverId, workspace.cwd); else onTerminal(workspace.serverId, workspace.sessionName ? 'tmux attach-session -t ' + shellQuote(workspace.sessionName) : workspace.cwd === '~' ? 'cd' : 'cd -- ' + shellQuote(workspace.cwd)); };
  return <section className="workcenter">
    <div className="workcenter-heading"><div><div className="eyebrow">SERVERCONSOLE</div><h1>{label('workCenter', 'Work center')}</h1></div><label>{label('server', 'Server')}<select disabled={busy} value={serverId} onChange={(e) => setServer(e.target.value)}>{servers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label><button className="btn" disabled={busy} onClick={() => setRevision((n) => n + 1)}><RefreshCw size={14} />{t('monitor.refresh')}</button></div>
    <nav className="workcenter-tabs" aria-label={label('workCenter', 'Work center')}>{groups.map((group) => <div className="workcenter-nav-group" key={group.key}><span>{group.title}</span><div>{group.tabs.map((key) => <button className={tab === key ? 'on' : ''} aria-current={tab === key ? 'page' : undefined} key={key} disabled={busy} onClick={() => { if (key === 'experiments') setSelectedWorkspace(''); setTab(key); }}>{titleOf(key)}</button>)}</div></div>)}</nav>
    {liveServer && <div className="workcenter-context" role="status"><i className={`dot ${liveServer.status}`} /><b>{liveServer.name}</b><code>{liveServer.host}</code><span>{label(liveServer.status, liveServer.status)}</span><span>{liveServer.collectedAt ? t('workbench.updated', { time: new Date(liveServer.collectedAt).toLocaleTimeString() }) : t('workbench.waiting')}</span></div>}
    {!api && <p className="note">{label('desktopRequired', 'Open the desktop application to use remote tools.')}</p>}
    {error && <p role="alert" className="monitor-error">{error}</p>}
    <fieldset disabled={busy} style={{ border: 0, padding: 0, margin: 0, minWidth: 0, display: 'grid', gap: 16 }}>{tab === 'system' && <><div className="workcenter-grid"><article className="card"><h2><Activity size={18} />{label('storage', 'Storage & inodes')}</h2><div className="workcenter-table"><table><thead><tr><th>{label('mount', 'Mount')}</th><th>{label('available', 'Available')}</th><th>{label('used', 'Used')}</th><th>Inodes</th></tr></thead><tbody>{resources?.filesystems.map((disk) => <tr key={disk.mount}><td title={disk.device}>{disk.mount}</td><td>{bytes(disk.available)}</td><td><meter value={disk.percent} min="0" max="100" /> {disk.percent}%</td><td>{resources.inodes.find((item) => item.mount === disk.mount)?.percent ?? '—'}%</td></tr>)}</tbody></table></div></article><article className="card"><h2>{label('diskIo', 'Disk I/O')}</h2>{resources?.disks.map((disk) => <p className="resource-line" key={disk.device}><b>{disk.device}</b><span>↓ {bytes(disk.readBytesPerSecond)}/s · ↑ {bytes(disk.writeBytesPerSecond)}/s · {disk.busyPercent?.toFixed(1) ?? '—'}%</span></p>)}<h2>{label('network', 'Network')}</h2>{resources?.networks.map((network) => <p className="resource-line" key={network.device}><b>{network.device}</b><span>↓ {bytes(network.receiveBytesPerSecond)}/s · ↑ {bytes(network.transmitBytesPerSecond)}/s</span></p>)}{resources && !resources.capabilities.ratesReady && <p className="note">{label('ratesNeedTwo', 'Rates appear after two observations.')}</p>}</article></div><article className="card"><h2>{label('processDetails', 'Process details')}</h2><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => setOutput(JSON.stringify(await request('process', { pid: Number(form.pid) }), null, 2))); }}>{input('pid', 'PID', 'number')}<button className="btn" disabled={busy}>{label('inspect', 'Inspect')}</button></form></article><article className="card"><h2>{label('envCompare', 'Environment comparison')}</h2><div className="workcenter-actions"><button className="btn" disabled={busy || !serverId} onClick={() => void run(async () => { await request('envCollect'); })}><RefreshCw size={13} />{label('envCollect', 'Collect this server')}</button><button className="btn" disabled={busy || !servers.length} onClick={() => void run(async () => { await Promise.allSettled(servers.map((s) => request('envCollect', { serverId: s.id }))); })}>{label('envCollectAll', 'Collect all servers')}</button></div><p className="note">{label('envNote', 'Differences from the majority value are highlighted. PyTorch requires torch to be importable by python3.')}</p>{envServers.length ? <div className="workcenter-table"><table><thead><tr><th></th>{envServers.map((s) => <th key={s.id}>{s.name}</th>)}</tr></thead><tbody>{envFields.map(([key, fallback, pick]) => { const counts = new Map<string, number>(); for (const s of envServers) { const value = pick(envOf(s.id)!); if (value !== '—') counts.set(value, (counts.get(value) || 0) + 1); } const majority = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0]; return <tr key={key}><th scope="row">{label(key, fallback)}</th>{envServers.map((s) => { const value = pick(envOf(s.id)!); return <td key={s.id} className={majority && value !== majority && value !== '—' ? 'env-diff' : ''}>{value}</td>; })}</tr>; })}</tbody></table></div> : <p className="note">{label('envNever', 'Not collected yet — use the buttons above.')}</p>}</article></>}
    {tab === 'tasks' && <><article className="card"><h2>{label('newTask', 'New task workspace')}</h2><details className="workcenter-create"><summary>{label('create', 'Create')}</summary><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { await request('taskSave', { name: form.name, cwd: form.cwd, command: form.command, gpu: form.gpu, ...(form.schedEnabled ? { schedule: { start: form.schedStart, end: form.schedEnd, days: [...form.schedDays].map(Number), enabled: true } } : {}) }); set('command', ''); }); }}>{input('name', label('name', 'Name'))}{input('cwd', label('directory', 'Working directory'))}{input('gpu', 'CUDA_VISIBLE_DEVICES')}<label className="wide">{label('command', 'Command')}<textarea required value={form.command} onChange={(e) => set('command', e.target.value)} /></label><div className="workcenter-form schedule-row"><label className="check"><input type="checkbox" checked={!!form.schedEnabled} onChange={(e) => set('schedEnabled', e.target.checked ? '1' : '')} />{label('scheduleToggle', 'Run on a schedule (time window)')}</label>{!!form.schedEnabled && <><label>{label('scheduleStart', 'Window start')}<input type="time" value={form.schedStart} onChange={(e) => set('schedStart', e.target.value)} /></label><label>{label('scheduleEnd', 'Window end')}<input type="time" value={form.schedEnd} onChange={(e) => set('schedEnd', e.target.value)} /></label><label className="wide">{label('scheduleDays', 'Days')}<span className="day-picker">{[[0, 'Su'], [1, 'Mo'], [2, 'Tu'], [3, 'We'], [4, 'Th'], [5, 'Fr'], [6, 'Sa']].map(([day, name]) => <button type="button" key={day} className={form.schedDays.includes(String(day)) ? 'on' : ''} onClick={() => set('schedDays', (() => { const cur = form.schedDays; const d = String(day); return [...cur].filter((c) => c !== d).concat(cur.includes(d) ? [] : [d]).sort().join(''); })())}>{name}</button>)}</span></label><p className="note wide">{label('scheduleNote', 'The app must be running to fire the window. Times follow the server\u2019s local clock; the process is started at window start and terminated at window end. Outside the window nothing runs on the server.')}</p></>}</div><button className="btn primary" disabled={busy}>{label('saveTask', 'Save task')}</button></form></details></article><div className="workcenter-grid">{tasks.map((task) => <article className="card" key={task.id}><h2>{task.name}<span className="badge">{task.schedule?.enabled && task.status === 'saved' ? label('waitingWindow', 'Waiting for window') : label(task.status, task.status)}</span></h2>{task.schedule?.enabled && <p className="resource-line"><b>⏰ {task.schedule.start}–{task.schedule.end}</b><span>· {task.schedule.days.length === 7 ? label('everyDay', 'Every day') : task.schedule.days.map((d) => [label('d0', 'Su'), label('d1', 'Mo'), label('d2', 'Tu'), label('d3', 'We'), label('d4', 'Th'), label('d5', 'Fr'), label('d6', 'Sa')][d]).join(' ')}</span></p>}<p className="mono">{task.cwd}</p><pre>{task.command}</pre>{task.exitCode != null && <p>{label('exitCode', 'Exit code')}: {task.exitCode}</p>}<div className="workcenter-actions"><button className="btn primary" disabled={busy || !!task.remoteId} onClick={() => void run(async () => { await request('taskStart', { id: task.id }); })}><Play size={13} />{label('start', 'Start')}</button>{['starting', 'running', 'unknown'].includes(task.status) && <button className="btn" disabled={busy} onClick={() => void run(async () => { await request('taskStop', { id: task.id }); })}>⏹ {label('stop', 'Stop')}</button>}<button className="btn" disabled={!task.remoteId || busy} onClick={() => void run(async () => { const result = await request<{ text: string }>('taskLog', { id: task.id }); setOutput(result.text); })}>{label('logs', 'Logs')}</button><button className="btn" onClick={() => onFiles(task.serverId, task.cwd === '~' ? undefined : task.cwd)}><FolderOpen size={13} />{t('nav.files')}</button><button className="btn" onClick={() => onTerminal(task.serverId, task.sessionName ? 'tmux attach-session -t ' + task.sessionName : task.cwd === '~' ? 'cd' : 'cd -- ' + "'" + task.cwd.replace(/'/g, "'\\''") + "'")}><Terminal size={13} />{label('openTerminal', 'Terminal')}</button><button className="btn" disabled={busy || ['starting', 'running', 'unknown'].includes(task.status)} onClick={() => void run(async () => { await request('taskDelete', { id: task.id }); })}>{label('remove', 'Remove')}</button></div></article>)}</div></>}
    {tab === 'watches' && <><div className="workcenter-grid"><article className="card"><h2><Bell size={18} />{label('gpuReminder', 'GPU availability reminder')}</h2><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { await request('watchSave', { model: form.model, minFreeGiB: Number(form.free), durationSeconds: Number(form.seconds) }); }); }}>{input('model', label('gpuModel', 'GPU model contains'))}{input('free', label('freeGiB', 'Minimum free GiB'), 'number')}{input('seconds', label('durationSeconds', 'Duration (seconds)'), 'number')}<button className="btn primary" disabled={busy}>{label('addReminder', 'Add reminder')}</button></form>{watches.map((watch) => <p className="resource-line" key={watch.id}><span>{watch.model || '*'} ≥{watch.minFreeGiB} GiB · {watch.durationSeconds}s · {watch.enabled ? label('enabled', 'Enabled') : label('fired', 'Fired')}</span><button className="btn mini" onClick={() => void run(async () => { await request('watchDelete', { id: watch.id }); })}>{label('remove', 'Remove')}</button></p>)}</article><article className="card"><h2>{label('alertRules', 'Alert rules')}</h2><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { await request('ruleSave', { name: form.name, metric: form.metric, direction: 'above', threshold: Number(form.threshold), recovery: Number(form.recovery), durationSeconds: Number(form.seconds), cooldownSeconds: Number(form.cooldown), quietStart: form.quietStart, quietEnd: form.quietEnd }); }); }}>{input('name', label('name', 'Name'))}<label>{label('metric', 'Metric')}<select value={form.metric} onChange={(e) => set('metric', e.target.value)}>{['temperature', 'memoryPercent', 'gpuUtil', 'cpuUsage', 'offline', 'occupiedIdle'].map((metric) => <option key={metric} value={metric}>{label(metric, metric)}</option>)}</select></label>{form.metric === 'occupiedIdle' && <p className="note wide">{label('occupiedIdleNote', 'Fires when a GPU holds memory but does no work: utilization stays below the threshold % while memory use stays above the recovery % for the whole duration. The event names the card and its users.')}</p>}{input('threshold', label('threshold', 'Threshold'), 'number')}{input('recovery', label('recovery', 'Recovery threshold'), 'number')}{input('seconds', label('durationSeconds', 'Duration (seconds)'), 'number')}{input('cooldown', label('cooldown', 'Cooldown (seconds)'), 'number')}{input('quietStart', label('quietStart', 'Quiet hours start'), 'time')}{input('quietEnd', label('quietEnd', 'Quiet hours end'), 'time')}<button className="btn primary" disabled={busy}>{label('addRule', 'Add rule')}</button></form>{rules.map((rule) => <p className="resource-line" key={rule.id}><span>{rule.name} · {label(rule.metric, rule.metric)} ≥{rule.threshold} · {rule.durationSeconds}s</span><button className="btn mini" onClick={() => void run(async () => { await request('ruleDelete', { id: rule.id }); })}>{label('remove', 'Remove')}</button></p>)}</article></div><article className="card"><h2>{label('events', 'Events')}</h2>{events.slice(0, 100).map((event) => <p key={event.id}><time>{new Date(event.at).toLocaleString()}</time> · <b>{event.title}</b> · {event.body}</p>)}</article></>}
    {tab === 'logs' && <><article className="card"><h2><FileText size={18} />{label('logWatchers', 'Log watchers')}</h2><p className="note">{label('logNote', 'The app reads new bytes every 5 seconds and notifies you when a new line matches any pattern. Patterns are regular expressions, one per line.')}</p><details id="log-create" className="workcenter-create" open={editingLog ? true : undefined}><summary>{editingLog ? label('editLog', 'Edit watcher') : label('addWatcher', 'Add watcher')}</summary><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); if (!form.logPatterns.trim() && !form.logLoss) { setError(label('logNeedsPattern', 'Add at least one pattern or enable loss tracking.')); return; } void run(async () => { await request('logSave', { id: editingLog?.id, enabled: editingLog?.enabled ?? true, name: form.logName || 'log', path: form.logPath, patterns: form.logPatterns.split(/\r?\n/).map((p) => p.trim()).filter(Boolean), patternMode: form.logMode, trackLoss: !!form.logLoss }); set('logName', ''); set('logPath', ''); set('logPatterns', ''); set('logLoss', ''); setEditingLog(null); }); }}>{input('logName', label('name', 'Name'))}<label className="wide">{label('logPath', 'Log file path (on the server)')}<input className="mono" required value={form.logPath} onChange={(e) => set('logPath', e.target.value)} placeholder="/root/runs/train.log" /></label><label className="wide">{label('logPatternsGeneric', 'Patterns (one per line)')}<textarea className="mono" value={form.logPatterns} onChange={(e) => set('logPatterns', e.target.value)} placeholder={'error\nCUDA out of memory'} /></label><label>{label('logPatternMode', 'Match mode')}<select value={form.logMode} onChange={(e) => set('logMode', e.target.value)}><option value="literal">{label('logLiteral', 'Text')}</option><option value="regex">{label('logRegex', 'Regular expression')}</option></select></label><label className="check"><input type="checkbox" checked={!!form.logLoss} onChange={(e) => set('logLoss', e.target.checked ? '1' : '')} />{label('logTrackLoss', 'Track loss values (sparkline)')}</label><button className="btn primary" disabled={busy}>{label('addWatcher', 'Add watcher')}</button></form></details></article><div className="workcenter-grid">{logWatchers.filter((log) => log.serverId === serverId).map((log) => <article className="card" key={log.id}><h2>{log.name}<span className="badge">{log.enabled ? label('enabled', 'Enabled') : label('paused', 'Paused')}</span></h2><p className="mono">{log.path}</p>{log.patterns.length > 0 && <p className="mono">{log.patterns.join(' · ')}</p>}{log.trackLoss && <Sparkline values={log.lossPoints || []} />}{log.progressPoints?.length ? <p className="resource-line"><span>{label('step', 'Step')} {log.progressPoints[log.progressPoints.length - 1]?.step ?? '—'}</span><span>{label('epoch', 'Epoch')} {log.progressPoints[log.progressPoints.length - 1]?.epoch ?? '—'}</span><span>loss {log.progressPoints[log.progressPoints.length - 1]?.loss ?? '—'}</span></p> : null}{log.lastPollAt && <p className="note">{new Date(log.lastPollAt).toLocaleTimeString()}{log.backlogBytes ? ' · ' + label('logBacklog', 'Remaining bytes') + ': ' + bytes(log.backlogBytes) : ''}</p>}{log.lastError && <p role="alert" className="monitor-error">{log.lastError}</p>}{log.pendingPreview?.length ? <details><summary>{label('logPendingPreview', 'Unprocessed log preview')}</summary><pre>{log.pendingPreview.join('\n')}</pre></details> : null}{(log.lastHits || []).length > 0 && <div>{(log.lastHits || []).slice(-3).reverse().map((hit, index) => <p key={hit.at + '-' + index}><time>{new Date(hit.at).toLocaleTimeString()}</time> · <span className="mono">{hit.line}</span></p>)}</div>}<div className="workcenter-actions"><button className="btn" disabled={busy} onClick={() => { setEditingLog({ id: log.id, enabled: log.enabled }); setForm((previous) => ({ ...previous, logName: log.name, logPath: log.path, logPatterns: log.patterns.join('\n'), logMode: log.patternMode || 'regex', logLoss: log.trackLoss ? '1' : '' })); document.getElementById('log-create')?.scrollIntoView({ block: 'start' }); }}>{label('editLog', 'Edit watcher')}</button><button className="btn primary" disabled={busy} onClick={() => void run(async () => { await request('logPoll', { id: log.id }); })}>{label('checkNow', 'Check now')}</button><button className="btn" disabled={busy} onClick={() => void run(async () => { await request('logSave', { id: log.id, name: log.name, path: log.path, patterns: log.patterns, patternMode: log.patternMode, trackLoss: log.trackLoss, enabled: !log.enabled }); })}>{log.enabled ? label('pause', 'Pause') : label('resume', 'Resume')}</button><button className="btn" disabled={busy} onClick={() => void run(async () => { await request('logDelete', { id: log.id }); })}>{label('remove', 'Remove')}</button></div></article>)}</div></>}
    {tab === 'sync' && <><article className="card"><h2>{label('syncTitle', 'Save & upload (Dev sync)')}</h2><p className="note">{label('syncNote', 'Watches a local folder and uploads every changed file to the server automatically (500 ms debounce). Excludes are glob patterns, one per line, e.g. **/*.tmp or node_modules.')}</p><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { if (!api) throw new Error(label('desktopRequired', 'Open the desktop application to use remote tools.')); await expectOk(api.devsyncSave({ localDir: form.syncLocal, remoteDir: form.syncRemote, serverId, excludes: form.syncExcludes.split(/\r?\n/).map((x) => x.trim()).filter(Boolean), enabled: true }), null); set('syncLocal', ''); set('syncRemote', ''); set('syncExcludes', ''); }); }}><label className="wide">{label('syncLocalDir', 'Local directory')}<span className="workcenter-actions"><input className="mono" required value={form.syncLocal} onChange={(e) => set('syncLocal', e.target.value)} placeholder="C:\projects\train" /><button type="button" className="btn" disabled={busy} onClick={async () => { const dir = await api?.dlgOpenDir(); if (dir) set('syncLocal', dir); }}>{label('browse', 'Browse…')}</button></span></label><label className="wide">{label('syncRemoteDir', 'Remote directory (on the server)')}<input className="mono" required value={form.syncRemote} onChange={(e) => set('syncRemote', e.target.value)} placeholder="/root/projects/train" /></label><label className="wide">{label('syncExcludes', 'Excludes (one glob per line)')}<textarea className="mono" value={form.syncExcludes} onChange={(e) => set('syncExcludes', e.target.value)} placeholder={'**/*.tmp\nnode_modules'} /></label><button className="btn primary" disabled={busy}>{label('addPair', 'Add pair')}</button></form></article><div className="workcenter-grid">{pairs.filter((pair) => pair.serverId === serverId).map((pair) => <article className="card" key={pair.id}><h2 className="mono" style={{ fontSize: 13, wordBreak: 'break-all' }}>{pair.localDir}<span className="badge">{pair.enabled ? label('enabled', 'Enabled') : label('paused', 'Paused')}</span></h2><p className="mono" style={{ wordBreak: 'break-all' }}>→ {pair.remoteDir}</p>{pair.status && <p role="status">{label('syncStatus.' + pair.status, pair.status)}</p>}<p><time>{label('lastSync', 'Last sync')}</time>: {pair.lastSyncAt ? new Date(pair.lastSyncAt).toLocaleString() : label('syncNever', 'No changes yet')}{pair.lastFiles?.length ? ` · ${pair.lastFiles.slice(-3).join(', ')}` : ''}</p>{pair.lastError && <p role="alert" className="monitor-error">{label('syncError', 'Watch error')}: {pair.lastError}</p>}<div className="workcenter-actions"><button className="btn" disabled={busy} onClick={() => void run(async () => { await expectOk(api?.devsyncToggle(pair.id, !pair.enabled), null); })}>{pair.enabled ? label('pause', 'Pause') : label('resume', 'Resume')}</button><button className="btn" disabled={busy} onClick={() => void run(async () => { const n = await expectOk(api?.devsyncPick(pair.id), 0); setOutput(label('pickOnce', 'Upload all now') + ': ' + n); })}>{label('pickOnce', 'Upload all now')}</button><button className="btn" disabled={busy} onClick={() => void run(async () => { await expectOk(api?.devsyncDelete(pair.id), true); })}>{label('remove', 'Remove')}</button></div></article>)}</div></>}
    {tab === 'containers' && <article className="card"><h2><Box size={18} />{containers?.engine || label('containers', 'Containers')}</h2>{containers && !containers.available && <p>{label('containersUnavailable', 'Docker or Podman is not installed.')}</p>}{containers?.statsError && <p className="note">{containers.statsError}</p>}<div className="workcenter-table"><table><thead><tr><th>{label('name', 'Name')}</th><th>{label('image', 'Image')}</th><th>{label('status', 'Status')}</th><th>CPU / RAM</th><th>{label('actions', 'Actions')}</th></tr></thead><tbody>{containers?.containers.map((container) => { const stats = containers.stats.find((item) => item.ID === container.id || container.id.startsWith(item.ID || '---') || item.Name === container.name); return <tr key={container.id}><td>{String(container.name)}</td><td>{container.image}</td><td>{container.status}</td><td>{stats?.CPUPerc || stats?.CPU || '—'} / {stats?.MemUsage || stats?.Mem || '—'}</td><td><button className="btn mini" onClick={() => void run(async () => { setOutput((await request<{ text: string }>('containerLogs', { engine: containers.engine, containerId: container.id })).text); })}>{label('logs', 'Logs')}</button><button className="btn mini" onClick={() => void run(async () => { onTerminal(serverId, (await request<{ command: string }>('containerShell', { engine: containers.engine, containerId: container.id })).command); })}>{label('openTerminal', 'Terminal')}</button></td></tr>; })}</tbody></table></div></article>}
    {tab === 'services' && <article className="card"><h2>{label('services', 'Services')}</h2><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { const template = await request<ServiceTemplate>('serviceTemplate', { name: form.service, remotePort: Number(form.remotePort), localPort: Number(form.localPort), logDir: form.logDir }); await onForward(serverId, template); if (mounted.current && generation.current === requestGeneration) setOutput(template.url + '\n' + template.command); }); }}><label>{label('service', 'Service')}<select value={form.service} onChange={(e) => { const service = e.target.value; set('service', service); set('remotePort', service === 'tensorboard' ? '6006' : '8888'); set('localPort', service === 'tensorboard' ? '6006' : '8888'); }}><option value="jupyter">Jupyter Lab</option><option value="tensorboard">TensorBoard</option><option value="web">Web</option></select></label>{input('remotePort', label('remotePort', 'Remote port'), 'number')}{input('localPort', label('localPort', 'Local port'), 'number')}{input('logDir', label('logDirectory', 'Log directory'))}<button className="btn primary" disabled={busy}>{label('openTunnel', 'Open tunnel & browser')}</button><button className="btn" type="button" onClick={() => void run(async () => { const template = await request<ServiceTemplate>('serviceTemplate', { name: form.service, remotePort: Number(form.remotePort), localPort: Number(form.localPort), logDir: form.logDir }); if (template.command) onTerminal(serverId, template.command); })}>{label('launchService', 'Launch in terminal')}</button></form><p className="note">{label('serviceNote', 'The service must be running remotely. Jupyter keeps its token authentication; paste the token in the browser when prompted.')}</p></article>}
    {tab === 'reports' && <article className="card"><h2>{label('weeklyReport', 'Weekly resource report')}</h2><div className="workcenter-actions"><button className="btn primary" disabled={busy} onClick={() => void run(async () => { setReport(await request<ResourceReport>('report')); })}>{label('generateReport', 'Generate report')}</button><button className="btn" disabled={!report} onClick={() => report && downloadText('server-console-weekly.json', JSON.stringify(report, null, 2), 'application/json')}><Download size={14} />JSON</button><button className="btn" disabled={!report} onClick={() => report && downloadText('server-console-weekly.csv', [['device', 'mean', 'peak', 'coverage_percent', 'busy_equivalent_hours'], ...report.devices.map((device) => [device.label, device.average, device.peak, device.coveragePercent, device.busyEquivalentHours])].map((row) => row.map(csvCell).join(',')).join('\r\n'))}>CSV</button></div>{report && <><p>{new Date(report.start).toLocaleString()} — {new Date(report.end).toLocaleString()}</p><div className="workcenter-table"><table><thead><tr><th>GPU</th><th>{label('average', 'Average')}</th><th>{label('peak', 'Peak')}</th><th>{label('coverage', 'Coverage')}</th><th>{label('busyHours', 'Busy-equivalent hours')}</th></tr></thead><tbody>{report.devices.map((device) => <tr key={device.device}><td>{device.label}</td><td>{device.average?.toFixed(1) ?? '—'}%</td><td>{device.peak ?? '—'}%</td><td>{device.coveragePercent.toFixed(1)}%</td><td>{device.busyEquivalentHours.toFixed(2)}</td></tr>)}</tbody></table></div><p className="note">{report.note}</p><p>{label('trackedTasks', 'Tracked tasks')}: {report.tasks.length}</p></>}</article>}
    {tab === 'reports' && <article className="card"><h2>{label('usageReport', 'GPU time by user')}</h2><p className="note">{label('usageNote', 'Time is credited to each distinct user of an active GPU, split evenly when a card is shared. Data accumulates from the monitoring history, so it only grows while the app runs.')}</p><div className="workcenter-actions">{input('usageDays', label('usageDays', 'Range (days)'), 'number')}<button className="btn primary" disabled={busy} onClick={() => { setUsage(null); setRevision((n) => n + 1); }}>{label('usageLoad', 'Load')}</button><button className="btn" disabled={!usage?.length} onClick={() => { if (!usage) return; const serverNames = [...new Set(usage.flatMap((row) => Object.keys(row.byServer)))]; downloadText('server-console-usage.csv', [['user', 'total_minutes', ...serverNames], ...usage.map((row) => [row.user, String(Math.round(row.totalMinutes * 10) / 10), ...serverNames.map((n) => row.byServer[n] != null ? String(Math.round(row.byServer[n] * 10) / 10) : '')])].map((r) => r.map(csvCell).join(',')).join('\r\n'), 'text/csv'); }}>CSV</button></div>{usage && (usage.length ? <div className="workcenter-table"><table><thead><tr><th>{label('user', 'User')}</th><th>{label('usageTotal', 'Total')}</th>{[...new Set(usage.flatMap((row) => Object.keys(row.byServer)))].map((name) => <th key={name}>{name}</th>)}</tr></thead><tbody>{usage.map((row) => <tr key={row.user}><td className="mono">{row.user}</td><td>{usageText(row.totalMinutes)}</td>{[...new Set(usage.flatMap((r) => Object.keys(r.byServer)))].map((name) => <td key={name}>{row.byServer[name] != null ? usageText(row.byServer[name]) : '—'}</td>)}</tr>)}</tbody></table></div> : <p className="note">{label('usageEmpty', 'No usage recorded in this range.')}</p>)}</article>}
    {tab === 'commands' && <article className="card"><h2>{label('commandTemplates', 'Command templates')}</h2><details className="workcenter-create"><summary>{label('create', 'Create')}</summary><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { await request('templateSave', { name: form.name, command: form.command }); }); }}>{input('name', label('name', 'Name'))}<label className="wide">{label('command', 'Command')}<textarea value={form.command} onChange={(e) => set('command', e.target.value)} placeholder="python train.py --data {{dataset}}" required /></label><button className="btn primary" disabled={busy}>{label('saveTemplate', 'Save template')}</button></form></details><label>{label('parameters', 'Parameters (JSON)')}<input className="mono" value={form.parameters} onChange={(e) => set('parameters', e.target.value)} /></label>{templates.map((template) => <div className="template-row" key={template.id}><b>{template.name}</b><code>{template.command}</code><button className="btn" disabled={busy} onClick={() => void run(async () => { const rendered = await request<{ command: string }>('templateRender', { id: template.id, parameters: JSON.parse(form.parameters) }); setOutput(rendered.command); })}>{label('preview', 'Preview')}</button><button className="btn" disabled={busy} onClick={() => void run(async () => { const rendered = await request<{ command: string }>('templateRender', { id: template.id, parameters: JSON.parse(form.parameters) }); onTerminal(serverId, rendered.command); })}>{label('runTerminal', 'Run in terminal')}</button><button className="btn" onClick={() => void run(async () => { await request('templateDelete', { id: template.id }); })}>{label('remove', 'Remove')}</button></div>)}</article>}
    {tab === 'experiments' && <Suspense fallback={<p>{t('research.loading')}</p>}><ResearchPane key={serverId + ':' + selectedWorkspace} servers={servers} serverId={serverId} workspaceId={selectedWorkspace || undefined} onTerminal={onTerminal} onFiles={onFiles} /></Suspense>}
    {tab === 'workspaces' && <><article className="card"><details><summary>{label('newWorkspace', 'New experiment workspace')}</summary><p className="note">{label('workspaceNote', 'Keep a directory, GPU selection, task, tmux session, log and service port together. Opening a workspace does not start a task.')}</p><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { await request('workspaceSave', { workspace: { ...workspaceForm, serverId, remotePort: Number(workspaceForm.remotePort) || undefined, localPort: Number(workspaceForm.localPort) || undefined } }); }); }}>{(['name', 'cwd', 'gpu', 'sessionName', 'logPath', 'remotePort', 'localPort'] as const).map((key) => <label key={key}>{label(key, key)}<input required={key === 'name' || key === 'cwd'} value={workspaceForm[key]} onChange={(e) => workspaceSet(key, e.target.value)} /></label>)}<label>{label('associatedTask', 'Associated task')}<select value={workspaceForm.taskId} onChange={(e) => workspaceSet('taskId', e.target.value)}><option value="">—</option>{tasks.map((task) => <option key={task.id} value={task.id}>{task.name}</option>)}</select></label><button className="btn primary">{label('save', 'Save')}</button></form></details></article><div className="workcenter-grid">{workspaces.map((workspace) => <article className="card workspace-card" key={workspace.id}><h2>{workspace.name}<span className="badge">{workspace.gpu ? 'GPU ' + workspace.gpu : label('workspace', 'Workspace')}</span></h2><p className="mono">{workspace.cwd}</p>{workspace.taskId && <p>{label('associatedTask', 'Associated task')}: {tasks.find((task) => task.id === workspace.taskId)?.name || workspace.taskId}</p>}{workspace.sessionName && <p>tmux · {workspace.sessionName}</p>}{workspace.logPath && <p className="mono">{workspace.logPath}</p>}<div className="workcenter-actions"><button className="btn" onClick={() => { setSelectedWorkspace(workspace.id); setTab('experiments'); }}>{t('research.title')}</button><button className="btn primary" onClick={() => openWorkspace(workspace, 'term')}><Terminal size={13} />{label('openTerminal', 'Terminal')}</button><button className="btn" onClick={() => openWorkspace(workspace, 'files')}><FolderOpen size={13} />{t('nav.files')}</button>{workspace.remotePort && <button className="btn" onClick={() => void run(async () => { const template = await request<ServiceTemplate>('serviceTemplate', { name: 'web', remotePort: workspace.remotePort, localPort: workspace.localPort || workspace.remotePort }); await onForward(serverId, template); })}>{label('openTunnel', 'Open tunnel & browser')}</button>}<button className="btn" onClick={() => void run(async () => { await request('workspaceDelete', { id: workspace.id }); })}>{label('remove', 'Remove')}</button></div></article>)}</div>{!workspaces.length && <p className="note">{label('noWorkspaces', 'No saved workspaces yet.')}</p>}</>}
    {tab === 'gpuDiagnostics' && <article className="card"><h2>{label('gpuDiagnostics', 'GPU diagnostics')}</h2><p className="note">{label('gpuDiagnosticsNote', 'Read driver capabilities, performance state, throttling, ECC, PCIe, NVLink and MIG information. Unsupported fields are reported as unavailable.')}</p><button className="btn primary" disabled={busy} onClick={() => void run(async () => setGpuDiagnostics(await request<GpuDiagnostics>('gpuDiagnostics')))}>{label('inspect', 'Inspect')}</button>{gpuDiagnostics && <>{!gpuDiagnostics.available && <p className="note">{label('gpuUnavailable', 'NVIDIA tools are not available on this server.')}</p>}<div className="workcenter-table"><table><thead><tr><th>GPU</th><th>{label('metric', 'Metric')}</th><th>{label('value', 'Value')}</th></tr></thead><tbody>{gpuDiagnostics.devices.flatMap((gpu) => Object.entries(gpu.metrics).map(([metric, item]) => <tr key={gpu.index + ':' + metric}><td title={gpu.uuid}>{gpu.index}</td><td>{label('diag_' + metric.replace(/\./g, '_'), metric)}</td><td>{item.supported ? item.value : label('unavailable', 'Unavailable')}</td></tr>))}</tbody></table></div><pre>{gpuDiagnostics.layout}{gpuDiagnostics.nvlink ? "\nNVLink\n" + gpuDiagnostics.nvlink : ""}</pre></>}</article>}
    {tab === 'slurm' && <article className="card"><h2>{label('slurm', 'Slurm jobs')}</h2>{slurm && !slurm.available && <p className="note">{label('slurmUnavailable', 'Slurm is not available on this server.')}</p>}{slurm?.available && <><div className="workcenter-table"><table><thead><tr>{['id', 'name', 'user', 'state', 'elapsed', 'nodes', 'reason'].map((key) => <th key={key}>{label(key, key)}</th>)}</tr></thead><tbody>{slurm.jobs?.map((job) => <tr key={job.id} onClick={() => setJobId(job.id)}>{['id', 'name', 'user', 'state', 'elapsed', 'nodes', 'reason'].map((key) => <td key={key}>{job[key]}</td>)}</tr>)}</tbody></table></div>{slurm.output && <pre>{slurm.output}</pre>}<form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => setOutput(JSON.stringify(await request('slurmDetail', { jobId }), null, 2))); }}><label>{label('jobId', 'Job ID')}<input value={jobId} inputMode="numeric" required onChange={(e) => setJobId(e.target.value)} /></label><button className="btn">{label('inspect', 'Inspect')}</button></form><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { const result = await request<{ text: string }>('slurmLog', { jobId }); setOutput(result.text); }); }}><p className="note">{label('slurmLogNote', 'Read the output file recorded by Slurm for the selected job.')}</p><button className="btn">{label('logs', 'Logs')}</button></form></>}</article>}
    {tab === 'tools' && <><article className="card"><h2>{label('diagnostics', 'Connection diagnostics')}</h2><p className="note">{label('diagnosticsNote', 'Check the connection, SSH tools, remote permissions, driver, SFTP, rsync and tmux. Export results after reviewing them.')}</p><div className="workcenter-actions"><button className="btn primary" disabled={busy} onClick={() => void run(async () => { const result = JSON.stringify(await request('diagnostics'), null, 2); setOutput(result); setDiagnosticsOutput(result); })}>{label('runDiagnostics', 'Run diagnostics')}</button><button className="btn" disabled={!diagnosticsOutput} onClick={() => downloadText('server-console-diagnostics.json', diagnosticsOutput, 'application/json')}><Download size={13} />{label('export', 'Export')}</button></div></article><article className="card"><h2>{label('notifications', 'Notifications')}</h2><form className="workcenter-form" onSubmit={(e) => { e.preventDefault(); void run(async () => { await request('notificationSave', { settings: notification }); notificationDirty.current = false; setNotification((old) => ({ ...old, url: '' })); }); }}><label className="check"><input type="checkbox" checked={notification.enabled} onChange={(e) => { notificationDirty.current = true; setNotification((old) => ({ ...old, enabled: e.target.checked })); }} />{label('enabled', 'Enabled')}</label><label className="wide">{label('webhookUrl', 'Webhook URL')}<input type="url" autoComplete="off" value={notification.url} onChange={(e) => { notificationDirty.current = true; setNotification((old) => ({ ...old, url: e.target.value })); }} /></label><button className="btn primary">{label('save', 'Save')}</button><button className="btn" type="button" onClick={() => void run(async () => { const result = await request<{ delivered: boolean; reason?: string }>('notificationTest'); if (!result.delivered) throw new Error(label('notificationNotDelivered', 'Notification not delivered') + ': ' + label('notificationReason.' + (result.reason || 'unknown'), result.reason || 'unknown')); setOutput(label('notificationSent', 'Test notification sent.')); })}>{label('sendTest', 'Send test')}</button></form></article><article className="card"><h2>{label('backup', 'Backup & migration')}</h2><div className="workcenter-actions"><button className="btn" disabled={busy} onClick={() => void run(async () => { const result = await request<Record<string, unknown>>('backupExport'); result.presentation = exportPresentationBackup(localStorage); downloadText('server-console-backup.json', JSON.stringify(result, null, 2), 'application/json'); })}><Download size={13} />{label('exportBackup', 'Export backup')}</button><label>{label('importBackup', 'Import backup')}<input type="file" accept="application/json,.json" onChange={(e) => { const version = ++backupRevision.current; const file = e.target.files?.[0]; setBackup(''); setBackupPreview(null); reviewedBackup.current = ''; setBackupReading(false); if (!file) return; if (file.size > 4 * 1024 * 1024) { setError(label('backupTooLarge', 'Backup must be smaller than 4 MiB.')); return; } setBackupReading(true); void file.text().then((value) => { if (mounted.current && version === backupRevision.current) setBackup(value); }).catch((error) => { if (mounted.current && version === backupRevision.current) setError(String(error)); }).finally(() => { if (mounted.current && version === backupRevision.current) setBackupReading(false); }); }} /></label><button className="btn" disabled={!backup || busy || backupReading} onClick={() => void run(async () => { if (!backupPreview) { const version = backupRevision.current; const source = backup; validatePresentationBackup(JSON.parse(source).presentation); const preview = await request('backupImport', { backup: JSON.parse(source), apply: false }); if (version === backupRevision.current) { reviewedBackup.current = source; setBackupPreview(preview); } } else { if (reviewedBackup.current !== backup || backupReading) throw new Error('Select and preview the current backup again.'); const imported = JSON.parse(backup); const operationId = crypto.randomUUID(); stagePresentationImport(localStorage, operationId, imported.presentation); const result = await request<{ status?: string }>('backupImport', { backup: imported, apply: true, operationId }); settlePresentationImport(localStorage, { operationId, status: result.status || 'committed' }); setBackup(''); setBackupPreview(null); setOutput(label('backupImportedRestart', 'Backup imported. Restart the app to apply appearance and terminal layout settings.')); } })}>{backupPreview ? label('confirmImport', 'Import selected backup') : label('preview', 'Preview')}</button></div>{importResults.slice(0, 5).map((result) => <p className="note" key={result.operationId}>{new Date(result.at).toLocaleString()} · {result.status === 'committed' ? label('backupImportedRestart', 'Backup imported. Restart the app to apply appearance and terminal layout settings.') : label('notificationReason.failed', 'Failed')} {result.error}</p>)}{backupPreview != null && <pre>{JSON.stringify(backupPreview, null, 2)}</pre>}<p className="note">{label('backupNote', 'Backups contain workspace configuration and rules. Review the exported file before sharing it; credentials are handled separately.')}</p></article></>}
    {output && <article className="card workcenter-output"><button className="btn mini" onClick={() => setOutput('')}>{t('settings.close')}</button><pre>{output}</pre></article>}
    </fieldset>
  </section>;
}

